interface EvictionPolicy<K> { fun pick(keys: List<K>): K }
class LruPolicy<K> : EvictionPolicy<K> { override fun pick(keys: List<K>) = keys.first() }

class Cache<K, V>(private val policy: EvictionPolicy<K>) : EvictionPolicy<K> by policy {
    private val items = mutableMapOf<K, V>()
}
